def div_first_even_odd(lst):
    first_even = None
    first_odd = None
    for num in lst:
        if num % 2 == 0 and first_even is None:
            first_even = num
        if num % 2 != 0 and first_odd is None:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break
    if first_even is None or first_odd is None:
        return "Both an even and an odd number must be present in the list"
    return first_even / first_odd

# Example usage
print(div_first_even_odd([1, 3, 5, 8, 10, 11]))   # 8 / 1 = 8.0
print(div_first_even_odd([7, 4, 2, 9]))           # 4 / 7 ≈ 0.5714
print(div_first_even_odd([2, 4, 6]))              # "Both an even and an odd number must be present in the list"
